import{_ as d,l as c,o as e,c as i,v as o,p as s,x as t,d as n,i as l,S as E}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"递归 CTE","description":"","frontmatter":{"title":"递归 CTE","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/recursive-cte.md","filePath":"cs/recursive-cte.md","lastUpdated":1789023840000}'),p={name:"cs/recursive-cte.md"};function h(T,a,_,A,C,u){const r=c("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="递归-cte" tabindex="-1">递归 CTE <a class="header-anchor" href="#递归-cte" aria-label="Permalink to &quot;递归 CTE&quot;">​</a></h1><div class="epigraph"><p>WITH RECURSIVE 把线性递归写成声明：锚点关系并上递归步，迭代到不动点；图上的路径是关系上的传递闭包。</p><footer>—— 据 SQL:1999 递归查询；Bancilhon and Ramakrishnan 对演绎数据库；Ramakrishnan and Gehrke 整理</footer></div><p><a href="/cs/subquery-decorrelation">上一课</a>把有限嵌套拉平。本课不重做半连接。缺口是<strong>无界深度</strong>：组织树、账单分录、图上可达。固定层数的自连接写不下「任意深度」。递归公共表表达式（CTE）用锚点查询 union 递归查询，语义是最小不动点（在单调、分层的限制下）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>关系代数的五种运算没有传递闭包。要「从根走到所有下属」，应用循环会丢掉声明性。演绎数据库用 Datalog 的最小模型；SQL 把其中线性递归收成 <code>WITH RECURSIVE</code>。缺口是：迭代如何定义、何时停、环怎么处理，而不是「语法里有个 WITH」。</p><p>锚点：不引用 CTE 名的查询，给出第 0 层。递归步：引用 CTE 名，把上一轮结果接到基表上（通常再连接边关系）。重复直到某轮没有新行（集合语义）或包计数稳定。SQL 对递归形状有限制：常见是线性递归（递归名在 FROM 里只出现一次），禁止在递归步里随意聚合或否定，以免失去单调性。</p><p><span class="marginnote">Datalog 的最小不动点要求正例程序。SQL 引擎用迭代加工作表实现，遇到环要用 <code>UNION</code>（集合）去重，否则 <code>UNION ALL</code> 会沿环无限长。CYCLE 子句是后来标准对环的显式检测。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>求值：工作表 ← 锚点；结果 ← 锚点；反复：新 ← 递归步(工作表)；把新行并入结果（集合则去重）；工作表 ← 新；直至新空。这是半朴素求值的简化：每轮只用上一轮新行，避免重复派生。</p><p>图查询：边表 <code>E(src,dst)</code>，锚点选起点，递归步 <code>工作表 ⋈_{id=src} E</code> 投影 <code>dst</code>。最短路、带权，要用额外列与「只保留更短」的规则，纯递归 CTE 能写但易错；本课不把图专用引擎当 SQL 递归的替代定义。</p>',10)),(e(),s(E,null,{default:t(()=>[l(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ANCHOR%5B%22%E9%94%9A%E7%82%B9%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20W%5B%22%E5%B7%A5%E4%BD%9C%E8%A1%A8%22%5D%0A%20%20W%20--%3E%20STEP%5B%22%E9%80%92%E5%BD%92%E6%AD%A5%22%5D%0A%20%20STEP%20--%3E%20NEW%5B%22%E6%96%B0%E8%A1%8C%22%5D%0A%20%20NEW%20--%3E%20UNION%5B%22%E5%B9%B6%E5%85%A5%E7%BB%93%E6%9E%9C%22%5D%0A%20%20NEW%20--%3E%20W%0A%20%20NEW%20--%3E%7C%22%E7%A9%BA%22%7C%20FIX%5B%22%E4%B8%8D%E5%8A%A8%E7%82%B9%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>递归 CTE 对优化器是另一个防火墙：不能把外层限行随便推进递归步（<code>LIMIT</code> 在外层常切断的是最终结果，不是迭代次数）。有的引擎提供 <code>SEARCH</code>/<code>CYCLE</code> 控制深度优先与环。计划上递归步每轮都是一次查询，连接算法每轮重选或固定——实现细节，语义仍是迭代并。</p><p>与窗口、分组不同：递归的输入规模随轮次变。基数估计对递归几乎没有好统计，计划往往保守。这不影响指称。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Datalog 的全体分层否定与魔法集改写。也不把图数据库的遍历代数写成 SQL 的超集——后课图库另开。相互递归、递归中的聚合（如公司树合计）在标准里受限，点名存在，不把每个方言扩展当主干。</p><p>后课默认：传递闭包与树展开用递归 CTE 声明；停机靠集合并或显式环检测。下一课把 <code>EXISTS</code>、交并差与半连接在用户语言里对齐。</p><p>递归是声明的迭代，不是存储过程里的游标循环。不动点一旦到，结果是关系。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>锚点给出第 0 层，递归步迭代到不动点；线性递归是 SQL 的常见子集。</li><li>环上必须去重或 CYCLE，否则 <code>UNION ALL</code> 不终止。</li><li>集合运算与 EXISTS 下一课，对照存在量化与差。</li><li>出处：SQL:1999；Bancilhon and Ramakrishnan；Ramakrishnan and Gehrke。</li></ul>',9))])}const B=d(p,[["render",h]]);export{S as __pageData,B as default};
